export const CLEAN_PORTFOLIO_HTML = "<!doctype html>\n<html lang=\"tr\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Müşteri Portföyü</title>\n<style>\n:root{--nav:#0b1730;--nav2:#101e39;--blue:#1769f6;--blue2:#eaf2ff;--bg:#f4f7fb;--panel:#fff;--line:#dce5ef;--text:#0f172a;--muted:#64748b;--green:#13ad63;--greenbg:#e9f9f0;--red:#ef3b4f;--redbg:#fff0f1;--amber:#f3a600;--amberbg:#fff7df;--purple:#7547e8;--purplebg:#f1ecff}\n*{box-sizing:border-box}html,body{margin:0;min-height:100%;font-family:Segoe UI,Arial,sans-serif;background:var(--bg);color:var(--text)}button,input,select,textarea{font:inherit}.app{min-height:100vh;display:grid;grid-template-columns:205px minmax(0,1fr)}.side{background:linear-gradient(180deg,var(--nav),#0b1830 72%,#081326);color:#fff;padding:18px 14px;display:flex;flex-direction:column;min-height:100vh}.brand{font-size:18px;font-weight:900;display:flex;align-items:center;gap:10px;margin-bottom:18px}.brand img{width:42px;height:42px;object-fit:contain}.nav{display:grid;gap:4px}.nav a{color:#dbe6f5;text-decoration:none;padding:10px 11px;border-radius:8px;font-weight:700;font-size:13px;display:flex;gap:9px;align-items:center}.nav a:hover,.nav a.active{background:var(--blue);color:#fff}.nav-spacer{height:10px;border-bottom:1px solid #24324b;margin-bottom:8px}.side-foot{margin-top:auto;background:#13233f;border:1px solid #213453;border-radius:12px;padding:12px}.side-foot b{display:block;font-size:12px;margin-bottom:9px}.side-foot .small-line{font-size:11px;color:#cbd5e1;padding:6px 0;border-top:1px solid #243653}.main{padding:18px 16px 20px;min-width:0}.head{display:flex;align-items:flex-start;justify-content:space-between;gap:14px;margin-bottom:14px}.head h1{margin:0;font-size:27px;line-height:1}.sub{color:var(--muted);font-size:12px;margin-top:7px}.head-actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.datebox,.btn{border:1px solid var(--line);background:#fff;border-radius:8px;padding:9px 12px;font-weight:800;color:#334155}.btn{cursor:pointer}.btn.primary{background:var(--blue);color:#fff;border-color:var(--blue)}.btn.soft{background:#f8fafc}.btn.small{padding:7px 10px;font-size:12px}.filter-grid{display:grid;grid-template-columns:140px 140px 150px 150px 150px minmax(230px,1fr) 88px 82px;gap:9px;align-items:end;margin-bottom:13px}.filter label{display:block;font-size:10px;font-weight:900;color:#334155;margin:0 0 5px 2px}.filter input,.filter select{width:100%;height:38px;border:1px solid var(--line);border-radius:8px;background:#fff;padding:0 10px;color:#0f172a}.cards{display:grid;grid-template-columns:repeat(8,minmax(118px,1fr));gap:10px;margin-bottom:13px}.stat{border:1px solid var(--line);border-radius:10px;background:#fff;padding:12px;display:grid;grid-template-columns:38px 1fr;gap:9px;align-items:center;min-height:78px}.stat .ico{width:38px;height:38px;border-radius:50%;display:grid;place-items:center;font-size:19px;font-weight:900}.stat .label{font-size:11px;font-weight:900;margin-bottom:2px}.stat .num{font-size:22px;font-weight:900;line-height:1}.stat .tiny{font-size:9px;color:var(--muted);margin-top:3px}.stat.total{background:#f4f8ff}.stat.total .ico{background:#dfeeff;color:#1769f6}.stat.pos{background:#f2fcf6}.stat.pos .ico{background:#dff7e9;color:#12a65d}.stat.wait{background:#fffaf0}.stat.wait .ico{background:#fff0c7;color:#d98e00}.stat.neg{background:#fff4f4}.stat.neg .ico{background:#ffe0e3;color:#e72f43}.stat.offer{background:#f7f4ff}.stat.offer .ico{background:#ece4ff;color:#7043dd}.stat.call{background:#fff9ed}.stat.call .ico{background:#ffedc4;color:#e49a00}.stat.order{background:#fff1f1}.stat.order .ico{background:#ffdadd;color:#e93449}.stat.over{background:#fff1f1}.stat.over .ico{background:#ffdadd;color:#e93449}.workbar{background:#fff;border:1px solid var(--line);border-radius:10px 10px 0 0;padding:8px 10px;display:flex;align-items:center;justify-content:space-between;gap:10px}.views{display:flex;gap:4px;align-items:center}.viewbtn{border:0;background:transparent;border-radius:7px;padding:7px 10px;font-size:11px;font-weight:800;color:#475569;cursor:pointer}.viewbtn.active{background:#eaf2ff;color:#1769f6}.workspace{display:grid;grid-template-columns:minmax(0,1.9fr) minmax(390px,.92fr);gap:10px;align-items:start}.table-card{background:#fff;border:1px solid var(--line);border-top:0;border-radius:0 0 10px 10px;overflow:auto;min-height:622px}table{border-collapse:collapse;width:100%;min-width:930px}th,td{padding:9px 8px;border-bottom:1px solid #e7edf4;text-align:left;font-size:11px;vertical-align:middle}th{background:#f8fafc;font-weight:900;position:sticky;top:0;z-index:2;color:#334155}tbody tr{cursor:pointer}tbody tr:hover td,tbody tr.selected td{background:#eef5ff}tbody tr.overdue td{background:#fff1f2}tbody tr.overdue.selected td{background:#ffe4e6}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:6px;background:#22c55e}.dot.red{background:#ef4444}.dot.amber{background:#f59e0b}.company{font-weight:900;font-size:11px}.person-role{display:block;color:#64748b;font-size:9px;margin-top:2px}.mail{color:#1769f6;text-decoration:none}.badge{display:inline-flex;align-items:center;justify-content:center;padding:4px 7px;border-radius:5px;font-weight:900;font-size:9px;white-space:nowrap}.badge.high{background:#ffdedf;color:#db2b3d}.badge.mid{background:#fff0cf;color:#a86700}.badge.low{background:#ddf7e9;color:#16814c}.badge.pos{background:#dff7e9;color:#15814b}.badge.neg{background:#ffe0e3;color:#b61f31}.badge.wait{background:#fff0cf;color:#a86700}.badge.offer{background:#dfeaff;color:#315ed2}.badge.open{background:#e7edf5;color:#475569}.follow.over{color:#e11d48;font-weight:900}.follow.today{color:#d97706;font-weight:900}.note-check{font-size:13px}.detail{background:#fff;border:1px solid var(--line);border-radius:10px;overflow:hidden;min-height:673px;position:sticky;top:10px}.detail-head{display:flex;align-items:center;justify-content:space-between;padding:12px 13px;border-bottom:1px solid var(--line)}.detail-title{display:flex;align-items:center;gap:8px;font-size:17px;font-weight:900}.status-dot{width:10px;height:10px;border-radius:50%;background:#20b467}.detail-actions{display:flex;gap:6px}.tabs{display:grid;grid-template-columns:repeat(5,1fr);gap:0;border-bottom:1px solid var(--line);padding:0 10px}.tab{border:0;background:#fff;padding:9px 5px;font-size:10px;font-weight:800;color:#475569;cursor:pointer;border-bottom:2px solid transparent}.tab.active{color:#1769f6;border-bottom-color:#1769f6}.detail-body{padding:12px}.summary4{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;margin-bottom:10px}.mini-card{border:1px solid var(--line);border-radius:8px;padding:9px 7px;background:#fff;min-height:62px}.mini-card .m-label{font-size:9px;color:#64748b;font-weight:800}.mini-card .m-value{font-size:11px;font-weight:900;margin-top:4px}.two-col{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-bottom:10px}.panel{border:1px solid var(--line);border-radius:9px;padding:11px;background:#fff}.panel h3{font-size:12px;margin:0 0 9px}.info-row{display:grid;grid-template-columns:22px 1fr;gap:5px;align-items:center;margin:7px 0;font-size:11px}.info-row .ico{color:#1769f6;font-size:14px}.info-row input,.info-row select{width:100%;height:30px;border:1px solid var(--line);border-radius:6px;padding:0 7px;font-size:10px}.notes-panel{border:1.5px solid #22c55e;border-radius:9px;margin-top:8px}.notes-title{padding:9px 10px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;font-size:12px;font-weight:900}.note-list{padding:7px 10px;display:grid;gap:6px;max-height:155px;overflow:auto}.note-row{display:grid;grid-template-columns:18px 1fr 22px;gap:5px;align-items:start;font-size:10px}.note-row input{width:14px;height:14px;margin:0}.note-row button{border:0;background:transparent;color:#94a3b8;cursor:pointer}.add-note{display:grid;grid-template-columns:1fr auto;gap:6px;border-top:1px solid var(--line);padding:8px}.add-note input{border:1px solid var(--line);border-radius:6px;padding:7px;font-size:10px}.follow-grid{display:grid;grid-template-columns:1fr 80px 1fr auto;gap:7px;align-items:end;margin-top:10px}.follow-grid label{font-size:9px;font-weight:900;color:#475569}.follow-grid input,.follow-grid select{height:34px;border:1px solid var(--line);border-radius:7px;padding:0 7px;font-size:10px}.savebar{display:flex;justify-content:flex-end;gap:7px;margin-top:10px}.alert{display:none;margin-top:10px;padding:9px 10px;border-radius:8px;background:#fff0f1;color:#b42335;border:1px solid #ffccd1;font-size:10px;font-weight:900}.alert.show{display:block}.history{display:grid;gap:7px}.history-item{border-left:3px solid #1769f6;background:#f8fafc;border-radius:7px;padding:8px 9px;font-size:10px}.empty-detail{padding:50px 20px;color:#64748b;text-align:center}.pager{display:flex;align-items:center;justify-content:space-between;padding:9px 12px;font-size:10px;color:#64748b}.legend{display:flex;gap:12px;flex-wrap:wrap}.legend span:before{content:\"\";display:inline-block;width:7px;height:7px;border-radius:50%;background:#22c55e;margin-right:4px}.legend .l-today:before{background:#f59e0b}.legend .l-over:before{background:#ef4444}.analysis-box{background:#eef5ff;border:1px solid #cddfff;border-radius:8px;padding:10px;font-size:10px;line-height:1.5}.hidden{display:none!important}\n@media(max-width:1380px){.cards{grid-template-columns:repeat(4,1fr)}.filter-grid{grid-template-columns:repeat(4,1fr)}.filter.search{grid-column:span 2}.workspace{grid-template-columns:minmax(0,1.45fr) 400px}}@media(max-width:1000px){.app{grid-template-columns:170px minmax(0,1fr)}.workspace{grid-template-columns:1fr}.detail{position:static}.cards{grid-template-columns:repeat(2,1fr)}.filter-grid{grid-template-columns:1fr 1fr}.filter.search{grid-column:span 2}}@media(max-width:720px){.app{display:block}.side{min-height:auto;padding:8px;position:sticky;top:0;z-index:50}.brand,.side-foot{display:none}.nav{display:flex;overflow:auto}.nav a{white-space:nowrap}.nav-spacer{display:none}.main{padding:10px}.head{align-items:center}.head h1{font-size:21px}.datebox{display:none}.cards{grid-template-columns:1fr 1fr}.filter-grid{grid-template-columns:1fr 1fr}.filter.search{grid-column:1/-1}.workspace{display:block}.detail{margin-top:10px}.summary4{grid-template-columns:1fr 1fr}.two-col{grid-template-columns:1fr}.follow-grid{grid-template-columns:1fr 1fr}.follow-grid .wide{grid-column:1/-1}}\n\n\n\n/* V8: okunabilirlik için yazı boyutları büyütüldü. */\nbody{font-size:14px!important}\n.nav a{font-size:14px!important}\n.side-foot b{font-size:13px!important}\n.side-foot .small-line{font-size:12px!important}\n.head h1{font-size:30px!important}\n.sub{font-size:13px!important}\n.filter label{font-size:12px!important}\n.filter input,.filter select{font-size:13px!important}\n.btn{font-size:14px!important}\n.btn.small{font-size:13px!important}\n.daily-eval-title h2{font-size:18px!important}\n.daily-eval-title span{font-size:12px!important}\n.stat .label{font-size:12px!important}\n.stat .num{font-size:24px!important}\n.stat .tiny{font-size:10px!important}\n.viewbtn{font-size:12px!important}\nth,td{font-size:12.5px!important}\n.company{font-size:13px!important}\n.person-role{font-size:11px!important}\n.badge{font-size:10.5px!important}\n.detail-title{font-size:20px!important}\n.tab{font-size:12px!important;padding:11px 7px!important}\n.detail-body{font-size:13px!important}\n.mini-card .m-label{font-size:11px!important}\n.mini-card .m-value{font-size:13px!important}\n.panel h3{font-size:14px!important}\n.info-row{font-size:13px!important}\n.info-row .ico{font-size:16px!important}\n.info-row input,.info-row select{font-size:12.5px!important;height:34px!important}\n.notes-title{font-size:14px!important}\n.note-list{font-size:12.5px!important}\n.note-row{font-size:12.5px!important}\n.add-note input{font-size:12.5px!important;height:36px!important}\n.follow-grid label{font-size:11px!important}\n.follow-grid input,.follow-grid select{font-size:12px!important;height:36px!important}\n.history-item{font-size:12px!important}\n.analysis-box{font-size:13px!important}\n.empty-detail{font-size:14px!important}\n.pager{font-size:12px!important}\n\n\n/* V15: Görüşmeler & Notlar sekmesinden doğrudan kayıt; notlarda tarih gösterimi. */\n.meeting-compose{display:grid;grid-template-columns:160px 190px minmax(0,1fr) auto;gap:9px;align-items:end}\n.meeting-compose .mc-field{display:grid;gap:5px}\n.meeting-compose label{font-size:11px;font-weight:900;color:#475569}\n.meeting-compose input,.meeting-compose select,.meeting-compose textarea{width:100%;border:1px solid var(--line);border-radius:8px;background:#fff;padding:8px 9px;font-size:12.5px}\n.meeting-compose input,.meeting-compose select{height:38px}\n.meeting-compose textarea{min-height:72px;resize:vertical;line-height:1.4}\n.meeting-compose .mc-note{grid-column:3}\n.meeting-status{font-size:12px;font-weight:800;margin-top:7px;color:#15814b}\n.note-main{display:grid;gap:2px}\n.note-date{font-size:10.5px;color:#64748b;font-weight:800}\n@media(max-width:980px){.meeting-compose{grid-template-columns:1fr 1fr}.meeting-compose .mc-note{grid-column:1/-1}.meeting-compose .mc-save{grid-column:1/-1;justify-self:end}}\n\n/* V14: Instant mod - müşteri kartı anında açılır, ağır geçmiş verisi sekmede yüklenir. */\n/* V13: Performans - yetkili detayları yalnızca tıklanınca DOM'a eklenir. */\n.contact-card{contain:layout paint style}\n.contacts-list{content-visibility:auto}\n/* V12: Firmaya birden fazla yetkili kişi eklenebilir; tıklayınca detay açılır. */\n.contacts-panel{border:1px solid var(--line);border-radius:9px;background:#fff;margin:10px 0;overflow:hidden}\n.contacts-head{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 12px;border-bottom:1px solid var(--line)}\n.contacts-head h3{margin:0;font-size:14px}\n.contacts-list{display:grid;gap:8px;padding:10px}\n.contact-card{border:1px solid var(--line);border-radius:9px;background:#f8fafc;overflow:hidden}\n.contact-summary{width:100%;border:0;background:transparent;display:grid;grid-template-columns:minmax(180px,1.1fr) minmax(130px,.8fr) auto;gap:10px;align-items:center;padding:10px 12px;text-align:left;cursor:pointer}\n.contact-summary:hover{background:#eef5ff}\n.contact-name{font-size:13px;font-weight:900;color:#0f172a}\n.contact-role{font-size:12px;color:#64748b;font-weight:800}\n.contact-arrow{font-size:14px;color:#64748b;transition:transform .18s ease}\n.contact-card.open .contact-arrow{transform:rotate(90deg)}\n.contact-details{display:none;border-top:1px solid var(--line);padding:10px 12px;background:#fff}\n.contact-card.open .contact-details{display:block}\n.contact-fields{display:grid;grid-template-columns:1fr 1fr;gap:9px}\n.contact-field{display:grid;gap:5px}\n.contact-field label{font-size:11px;font-weight:900;color:#475569}\n.contact-field input{width:100%;height:36px;border:1px solid var(--line);border-radius:7px;padding:0 9px;font-size:12.5px}\n.contact-actions{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:9px;flex-wrap:wrap}\n.contact-links{display:flex;gap:7px;flex-wrap:wrap}\n.contact-link{display:inline-flex;align-items:center;gap:5px;text-decoration:none;border:1px solid var(--line);border-radius:7px;padding:7px 9px;font-size:12px;font-weight:900;background:#fff;color:#1769f6}\n.contact-empty{padding:12px;color:#64748b;font-size:12px}\n@media(max-width:760px){.contact-summary{grid-template-columns:1fr auto}.contact-role{grid-column:1/-1}.contact-fields{grid-template-columns:1fr}}\n\n/* V11: Mail sekmesi en sağda, tüm sekmeler soldan sağa tek sıra. */\n.mail-item{border:1px solid var(--line);border-left:4px solid #1769f6;border-radius:9px;padding:10px 12px;background:#fff}\n.mail-item.incoming{border-left-color:#16a34a}\n.mail-item.outgoing{border-left-color:#2563eb}\n.mail-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:6px}\n.mail-dir{font-size:11px;font-weight:900;padding:4px 8px;border-radius:999px}\n.mail-dir.incoming{background:#dcfce7;color:#166534}\n.mail-dir.outgoing{background:#dbeafe;color:#1d4ed8}\n.mail-subject{font-size:13px;font-weight:900}\n.mail-meta{font-size:11px;color:#64748b;margin-bottom:5px}\n.mail-summary{font-size:12.5px;line-height:1.45;color:#334155}\n.tabs{grid-template-columns:repeat(5,minmax(120px,1fr))!important}\n\n/* V9: eski Müşteri Analizi alanları geri getirildi. */\n.analysis-form{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:12px}\n.analysis-field{display:grid;gap:6px}\n.analysis-field.full{grid-column:1/-1}\n.analysis-field label{font-size:12px;font-weight:900;color:#475569}\n.analysis-field select,.analysis-field textarea{\n  width:100%;border:1px solid var(--line);border-radius:8px;background:#fff;\n  padding:9px 10px;font-size:13px;color:#0f172a\n}\n.analysis-field select{height:38px}\n.analysis-field textarea{min-height:92px;resize:vertical;line-height:1.45}\n.analysis-save-row{display:flex;align-items:center;justify-content:flex-end;gap:10px;margin-top:10px}\n.analysis-save-status{font-size:12px;font-weight:800;color:#15814b}\n@media(max-width:900px){.analysis-form{grid-template-columns:1fr}.analysis-field.full{grid-column:auto}}\n\n/* V7: tablo boşken tüm alanı kullanır; müşteri seçilince geniş sağ detay paneli açılır. */\n.app{grid-template-columns:178px minmax(0,1fr)!important}\n.main{padding:12px 10px 16px!important}\nbody:not(.customer-open) .workspace{grid-template-columns:minmax(0,1fr)!important}\nbody:not(.customer-open) .workspace .detail{display:none!important}\nbody:not(.customer-open) .table-card{min-height:650px}\nbody.customer-open .head,\nbody.customer-open .filter-grid,\nbody.customer-open .cards,\nbody.customer-open .daily-eval-title,\nbody.customer-open .workbar,\nbody.customer-open .table-card{display:revert!important}\nbody.customer-open .workspace{\n  display:grid!important;\n  grid-template-columns:minmax(560px,.92fr) minmax(690px,1.08fr)!important;\n  gap:12px!important;\n  align-items:start!important\n}\nbody.customer-open .detail{\n  display:block!important;\n  position:sticky!important;\n  top:8px!important;\n  width:auto!important;\n  min-height:calc(100vh - 28px)!important;\n  max-height:calc(100vh - 28px)!important;\n  overflow:hidden!important;\n  border-radius:12px!important\n}\nbody.customer-open .detail-body{\n  max-width:none!important;\n  margin:0!important;\n  max-height:calc(100vh - 126px)!important;\n  overflow:auto!important;\n  padding:14px!important\n}\nbody.customer-open .detail-close{display:inline-flex!important}\nbody.customer-open .summary4{grid-template-columns:repeat(4,minmax(110px,1fr))!important}\nbody.customer-open .two-col{grid-template-columns:1fr 1fr!important}\nbody.customer-open .tabs{grid-template-columns:repeat(5,minmax(100px,1fr))!important}\nbody.customer-open .table-card{min-height:calc(100vh - 335px)!important}\nbody.customer-open table{min-width:920px!important}\n@media(max-width:1350px){\n  body.customer-open .workspace{grid-template-columns:minmax(500px,.9fr) minmax(560px,1.1fr)!important}\n  body.customer-open .two-col{grid-template-columns:1fr!important}\n}\n@media(max-width:1050px){\n  .app{grid-template-columns:1fr!important}\n  .side{display:none!important}\n  body.customer-open .workspace{grid-template-columns:1fr!important}\n  body.customer-open .detail{position:static!important;max-height:none!important}\n  body.customer-open .detail-body{max-height:none!important}\n}\n#buildMarker{position:fixed;right:8px;bottom:8px;z-index:99999;background:#0b1730;color:#fff;border-radius:6px;padding:4px 7px;font-size:10px;font-weight:900;opacity:.82;pointer-events:none}\n.daily-eval-title{display:flex;align-items:end;justify-content:space-between;gap:10px;margin:2px 0 8px}\n.daily-eval-title h2{margin:0;font-size:16px}\n.daily-eval-title span{font-size:11px;color:#64748b;font-weight:800}\n.company-open-btn{appearance:none;border:0;background:transparent;padding:0;color:#1769f6;text-decoration:underline;text-underline-offset:2px;cursor:pointer;text-align:left}\n.detail-close{display:none}\nbody.customer-open .head,\nbody.customer-open .filter-grid,\nbody.customer-open .cards,\nbody.customer-open .daily-eval-title,\nbody.customer-open .workbar,\nbody.customer-open .table-card{display:none!important}\nbody.customer-open .workspace{display:block!important}\nbody.customer-open .detail{position:static!important;top:auto!important;min-height:calc(100vh - 36px)!important;width:100%!important;border-radius:10px!important}\nbody.customer-open .detail-close{display:inline-flex!important}\nbody.customer-open .detail-body{max-width:1500px;margin:0 auto}\nbody.customer-open .tabs{grid-template-columns:repeat(5,minmax(120px,1fr))}\n@media(max-width:720px){body.customer-open .detail{min-height:calc(100vh - 20px)!important}}\n</style>\n</head>\n<body><div id=\"buildMarker\">PORTFOY RICH V16</div>\n<div class=\"app\">\n<aside class=\"side\">\n  <div class=\"brand\"><img src=\"/notes-logo-ag-v1.webp\" alt=\"AG\"><span>CRM Müşteri<br>Takip</span></div>\n  <nav class=\"nav\">\n    <a href=\"/\">⌂ Ana Ekran</a>\n    <a href=\"/?page=customers\">♟ Müşteriler</a>\n    <a class=\"active\" href=\"/musteri-portfoyu.html\">▣ Müşteri Portföyü</a>\n    <div class=\"nav-spacer\"></div>\n    <a href=\"/?page=mails\">✉ Mailler</a>\n    <a href=\"/?page=graphicJobs\">▤ Grafik İşleri</a>\n    <a href=\"/?page=tracking\">✓ Takip</a>\n    <a href=\"/?page=reports\">▥ Raporlama</a>\n    <div class=\"nav-spacer\"></div>\n    <a href=\"/?page=agenda\">▣ Ajanda</a>\n    <a href=\"/\">⚙ Ayarlar</a>\n  </nav>\n  <div class=\"side-foot\"><b>Bugünün Hatırlatmaları</b><div id=\"sideReminders\" class=\"small-line\">Yükleniyor...</div></div>\n</aside>\n<main class=\"main\">\n  <div class=\"head\">\n    <div><h1>Müşteri Portföyü</h1><div class=\"sub\">Şehir özelinde müşteri analizleri, görüşme notları ve satış potansiyeli</div></div>\n    <div class=\"head-actions\"><span id=\"rangeBox\" class=\"datebox\"></span><button class=\"btn primary\" onclick=\"loadAll()\">↻ Yenile</button><a class=\"btn primary\" href=\"/?page=customers\">＋ Yeni Müşteri</a></div>\n  </div>\n\n  <div class=\"filter-grid\">\n    <div class=\"filter\"><label>İl / Bölge</label><select id=\"city\"><option value=\"\">Tümü</option></select></div>\n    <div class=\"filter\"><label>İş Alanı</label><select id=\"sector\"><option value=\"\">Tümü</option></select></div>\n    <div class=\"filter\"><label>Potansiyel</label><select id=\"priority\"><option value=\"\">Tümü</option><option>KRİTİK</option><option>YÜKSEK</option><option>NORMAL</option></select></div>\n    <div class=\"filter\"><label>Sonuç</label><select id=\"result\"><option value=\"\">Tümü</option><option value=\"positive\">Olumlu</option><option value=\"waiting\">Beklemede</option><option value=\"negative\">Olumsuz</option><option value=\"open\">Sonuçlanmamış</option></select></div>\n    <div class=\"filter\"><label>Takip</label><select id=\"followFilter\"><option value=\"\">Tümü</option><option value=\"overdue\">Süresi Geçen</option><option value=\"today\">Bugün</option><option value=\"future\">Yaklaşan</option></select></div>\n    <div class=\"filter search\"><label>Arama</label><input id=\"search\" placeholder=\"Firma, kişi, telefon, mail ara...\"></div>\n    <button class=\"btn primary\" onclick=\"render()\">⌕ Ara</button>\n    <button class=\"btn soft\" onclick=\"clearFilters()\">Temizle</button>\n  </div>\n\n  <div class=\"daily-eval-title\"><div><h2>Günlük Değerlendirme</h2><span id=\"dailyEvalDate\"></span></div><div class=\"sub\">Portföy, görüşme ve takip özeti</div></div>\n\n  <div class=\"cards\">\n    <div class=\"stat total\"><div class=\"ico\">▦</div><div><div class=\"label\">Toplam Firma</div><div id=\"sTotal\" class=\"num\">0</div><div class=\"tiny\">Portföy</div></div></div>\n    <div class=\"stat pos\"><div class=\"ico\">✓</div><div><div class=\"label\">Olumlu</div><div id=\"sPositive\" class=\"num\">0</div><div class=\"tiny\">Kazanılan</div></div></div>\n    <div class=\"stat wait\"><div class=\"ico\">◷</div><div><div class=\"label\">Beklemede</div><div id=\"sWaiting\" class=\"num\">0</div><div class=\"tiny\">Takipte</div></div></div>\n    <div class=\"stat neg\"><div class=\"ico\">×</div><div><div class=\"label\">Olumsuz</div><div id=\"sNegative\" class=\"num\">0</div><div class=\"tiny\">Sonuçlandı</div></div></div>\n    <div class=\"stat offer\"><div class=\"ico\">▤</div><div><div class=\"label\">Teklif Bekliyor</div><div id=\"sOffer\" class=\"num\">0</div><div class=\"tiny\">Teklif aşaması</div></div></div>\n    <div class=\"stat call\"><div class=\"ico\">☎</div><div><div class=\"label\">Tekrar Aranacak</div><div id=\"sFollow\" class=\"num\">0</div><div class=\"tiny\">Takip tarihi var</div></div></div>\n    <div class=\"stat order\"><div class=\"ico\">◇</div><div><div class=\"label\">Sipariş Alınan</div><div id=\"sOrder\" class=\"num\">0</div><div class=\"tiny\">Olumlu müşteri</div></div></div>\n    <div class=\"stat over\"><div class=\"ico\">●</div><div><div class=\"label\">Süresi Geçen</div><div id=\"sOverdue\" class=\"num\">0</div><div class=\"tiny\">Acil takip</div></div></div>\n  </div>\n\n  <div class=\"workbar\"><div class=\"views\"><button class=\"viewbtn active\">▦ Liste Görünümü</button><button class=\"viewbtn\">▣ Kart Görünümü</button><button class=\"viewbtn\">⌁ Analiz</button><button class=\"viewbtn\">⌖ Harita</button><button class=\"viewbtn\">◷ Zaman Çizelgesi</button></div><div><button class=\"btn small soft\" onclick=\"exportCsv()\">⇩ Dışa Aktar</button></div></div>\n\n  <div class=\"workspace\">\n    <div class=\"table-card\">\n      <table><thead><tr><th>Firma</th><th>Görüşülen Kişi</th><th>Telefon</th><th>İş Alanı</th><th>Son Görüşme</th><th>Potansiyel</th><th>Sonuç</th><th>Sonraki İşlem</th><th>Not</th><th>Aksiyon</th></tr></thead><tbody id=\"rows\"></tbody></table>\n      <div class=\"pager\"><div id=\"rowCount\">0 firma</div><div class=\"legend\"><span>Zamanında</span><span class=\"l-today\">Bugün</span><span class=\"l-over\">Süresi Geçti</span></div></div>\n    </div>\n\n    <aside id=\"detail\" class=\"detail\">\n      <div id=\"detailEmpty\" class=\"empty-detail\">Listeden bir müşteri seçin.</div>\n      <div id=\"detailContent\" class=\"hidden\">\n        <div class=\"detail-head\"><div class=\"detail-title\"><span class=\"status-dot\"></span><span id=\"dCompany\">Firma</span></div><div class=\"detail-actions\"><button type=\"button\" class=\"btn small detail-close\" onclick=\"closeCustomerDetail()\">← Müşteri Listesine Dön</button><button class=\"btn small\" onclick=\"focusEdit()\">✎ Düzenle</button></div></div>\n        <div class=\"tabs\"><button class=\"tab active\" data-tab=\"general\">Genel</button><button class=\"tab\" data-tab=\"notes\">Görüşmeler & Notlar</button><button class=\"tab\" data-tab=\"offers\">Teklifler</button><button class=\"tab\" data-tab=\"analysis\">Analiz</button><button class=\"tab\" data-tab=\"mails\">Mailler</button></div>\n        <div class=\"detail-body\">\n          <div id=\"tabGeneral\" class=\"tabpane\">\n            <div class=\"summary4\">\n              <div class=\"mini-card\"><div class=\"m-label\">Son Görüşme</div><div id=\"dLastMeeting\" class=\"m-value\">—</div></div>\n              <div class=\"mini-card\"><div class=\"m-label\">Sonuç</div><div id=\"dResultLabel\" class=\"m-value\">—</div></div>\n              <div class=\"mini-card\"><div class=\"m-label\">Sonraki İşlem</div><div id=\"dFollowLabel\" class=\"m-value\">—</div></div>\n              <div class=\"mini-card\"><div class=\"m-label\">Potansiyel</div><div id=\"dPotential\" class=\"m-value\">—</div></div>\n            </div>\n            <div class=\"two-col\">\n              <div class=\"panel\"><h3>İletişim Bilgileri</h3>\n                <div class=\"info-row\"><span class=\"ico\">●</span><input id=\"dContact\" placeholder=\"Görüşülen kişi\"></div>\n                <div class=\"info-row\"><span class=\"ico\">☎</span><input id=\"dPhone\" placeholder=\"Telefon\"></div>\n                <div class=\"info-row\"><span class=\"ico\">✉</span><input id=\"dEmail\" placeholder=\"Mail\"></div>\n                <div class=\"info-row\"><span class=\"ico\">⌖</span><input id=\"dRegion\" placeholder=\"İl / Bölge\"></div>\n              </div>\n              <div class=\"panel\"><h3>Firma Bilgileri</h3>\n                <div class=\"info-row\"><span class=\"ico\">▦</span><input id=\"dCategories\" placeholder=\"İş alanı\"></div>\n                <div class=\"info-row\"><span class=\"ico\">▥</span><select id=\"dPriority\"><option>KRİTİK</option><option>YÜKSEK</option><option>NORMAL</option></select></div>\n                <div class=\"info-row\"><span class=\"ico\">◉</span><select id=\"dResultSelect\"><option value=\"open\">Sonuçlanmamış</option><option value=\"waiting\">Beklemede</option><option value=\"positive\">Olumlu</option><option value=\"negative\">Olumsuz</option></select></div>\n                <div class=\"info-row\"><span class=\"ico\">▣</span><input id=\"dMachine\" placeholder=\"Makine / teknik bilgi\"></div>\n              </div>\n            </div>\n            <div class=\"contacts-panel\">\n              <div class=\"contacts-head\">\n                <h3>Yetkili Kişiler</h3>\n                <button type=\"button\" class=\"btn small primary\" onclick=\"addContactPerson()\">＋ Yetkili Ekle</button>\n              </div>\n              <div id=\"contactPeople\" class=\"contacts-list\"></div>\n            </div>\n            <div class=\"notes-panel\"><div class=\"notes-title\"><span>✓ Notlar</span><span>↗</span></div><div id=\"noteList\" class=\"note-list\"></div><div class=\"add-note\"><input id=\"newNote\" placeholder=\"Yeni not yazın...\"><button class=\"btn small primary\" onclick=\"addNote()\">＋ Ekle</button></div></div>\n            <div class=\"follow-grid\"><div><label>Sonraki İşlem Tarihi</label><input id=\"dFollow\" type=\"date\"></div><div><label>Saat</label><input id=\"dFollowTime\" type=\"time\" value=\"10:00\"></div><div class=\"wide\"><label>Hatırlatma Notu</label><input id=\"dReminderNote\" placeholder=\"Örn. Teklif sonucunu sor\"></div><button class=\"btn primary\" onclick=\"createReminder()\">🔔 Bildirim Ekle</button></div>\n            <div class=\"savebar\"><button class=\"btn soft\" onclick=\"loadSelected()\">İptal</button><button class=\"btn primary\" onclick=\"saveCustomer()\">Kaydet</button></div>\n            <div id=\"overdueAlert\" class=\"alert\">🔔 Bu müşterinin takip süresi geçti.</div>\n          </div>\n          <div id=\"tabNotes\" class=\"tabpane hidden\">\n            <div class=\"panel\">\n              <h3>Yeni Görüşme / Not Ekle</h3>\n              <div class=\"meeting-compose\">\n                <div class=\"mc-field\"><label>Tarih</label><input id=\"meetingNoteDate\" type=\"date\"></div>\n                <div class=\"mc-field\"><label>Sonuç</label><select id=\"meetingNoteResult\"><option>Beklemede</option><option>Tekrar Görüşülecek</option><option>Olumlu</option><option>Olumsuz</option></select></div>\n                <div class=\"mc-field mc-note\"><label>Görüşme / Not</label><textarea id=\"meetingNoteText\" placeholder=\"Müşteriyle konuşulanları veya notunuzu yazın...\"></textarea></div>\n                <button id=\"meetingNoteSave\" type=\"button\" class=\"btn primary mc-save\" onclick=\"saveMeetingNote()\">＋ Kaydet</button>\n              </div>\n              <div id=\"meetingNoteStatus\" class=\"meeting-status\"></div>\n            </div>\n            <div class=\"panel\" style=\"margin-top:12px\"><h3>Görüşme Geçmişi</h3><div id=\"meetingHistory\" class=\"history\"></div></div>\n          </div>\n          <div id=\"tabOffers\" class=\"tabpane hidden\"><div class=\"panel\"><h3>Teklifler</h3><div id=\"offerHistory\" class=\"history\"></div></div></div>\n          \n          <div id=\"tabAnalysis\" class=\"tabpane hidden\">\n            <div class=\"panel\">\n              <h3>Müşteri Analizi</h3>\n              <div class=\"analysis-form\">\n                <div class=\"analysis-field\">\n                  <label>Memnuniyet Durumu</label>\n                  <select id=\"aSatisfaction\">\n                    <option value=\"\">Belirtilmedi</option>\n                    <option value=\"Çok Memnun\">Çok Memnun</option>\n                    <option value=\"Memnun\">Memnun</option>\n                    <option value=\"Nötr\">Nötr</option>\n                    <option value=\"Memnun Değil\">Memnun Değil</option>\n                  </select>\n                </div>\n                <div class=\"analysis-field\">\n                  <label>Şikayet Durumu</label>\n                  <select id=\"aComplaintStatus\">\n                    <option value=\"\">Belirtilmedi</option>\n                    <option value=\"Yok\">Yok</option>\n                    <option value=\"Açık\">Açık</option>\n                    <option value=\"Takip Ediliyor\">Takip Ediliyor</option>\n                    <option value=\"Çözüldü\">Çözüldü</option>\n                  </select>\n                </div>\n                <div class=\"analysis-field full\">\n                  <label>Şikayet / Çözüm Notu</label>\n                  <textarea id=\"aComplaintNote\" placeholder=\"Şikayet, alınan aksiyon ve çözüm bilgisini yazın...\"></textarea>\n                </div>\n                <div class=\"analysis-field full\">\n                  <label>Kaybedilme Sebebi</label>\n                  <textarea id=\"aLossReason\" placeholder=\"Müşteri kaybedildiyse sebebini yazın...\"></textarea>\n                </div>\n              </div>\n              <div class=\"analysis-save-row\">\n                <span id=\"analysisSaveStatus\" class=\"analysis-save-status\"></span>\n                <button class=\"btn primary\" onclick=\"saveCustomerAnalysis()\">Müşteri Analizini Kaydet</button>\n              </div>\n            </div>\n            <div class=\"panel\" style=\"margin-top:12px\">\n              <h3>Otomatik Analiz</h3>\n              <div id=\"analysisBox\" class=\"analysis-box\"></div>\n            </div>\n          </div>\n          <div id=\"tabMails\" class=\"tabpane hidden\">\n            <div class=\"panel\">\n              <h3>Müşteriye Ait Mailler</h3>\n              <div id=\"mailHistory\" class=\"history\"></div>\n            </div>\n          </div>\n        </div>\n      </div>\n    </aside>\n  </div>\n</main>\n</div>\n<script>\nconst $=id=>document.getElementById(id);let customers=[],meetings=[],selected=null,selectedHistory=null,notes=[],contacts=[],visibleRows=[],openContactIndex=-1,portfolioLoadInFlight=false,meetingLoadInFlight=false,historyLoadInFlight=false,historyLoadedId=0,meetingDelayTimer=null;\nconst today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Istanbul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());\nconst esc=s=>String(s??'').replace(/[&<>\"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot',\"'\":'&#39;'}[m]));\nasync function api(url,opt={}){const r=await fetch(url,{credentials:'same-origin',headers:{'content-type':'application/json',...(opt.headers||{})},...opt});if(r.status===401){location.href='/';throw new Error('Oturum gerekli')}let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||'İşlem başarısız');return d}\nfunction parsed(v){try{const a=JSON.parse(v||'');return Array.isArray(a)?a:[]}catch{return []}}\nfunction customerContacts(c){\n  const list=parsed(c?.contacts_json).map(x=>({name:String(x?.name||''),role:String(x?.role||''),phone:String(x?.phone||''),email:String(x?.email||'')})).filter(x=>x.name||x.role||x.phone||x.email);\n  if(list.length)return list;\n  const fallback={name:String(c?.contact_name||''),role:'',phone:String(c?.phone||parsed(c?.phones_json)[0]||''),email:String(c?.email||parsed(c?.emails_json)[0]||'')};\n  return (fallback.name||fallback.phone||fallback.email)?[fallback]:[];\n}\nfunction renderContacts(){\n  const box=$('contactPeople');if(!box)return;\n  if(!contacts.length){box.innerHTML='<div class=\"contact-empty\">Henüz yetkili kişi eklenmemiş.</div>';return}\n  box.innerHTML=contacts.map((c,i)=>{\n    const open=i===openContactIndex;\n    return `<div class=\"contact-card ${open?'open':''}\" id=\"contactCard${i}\">\n      <button type=\"button\" class=\"contact-summary\" onclick=\"toggleContactPerson(${i})\">\n        <span class=\"contact-name\">${esc(c.name||'İsimsiz Yetkili')}</span>\n        <span class=\"contact-role\">${esc(c.role||'Görev belirtilmedi')}</span>\n        <span class=\"contact-arrow\">›</span>\n      </button>\n      ${open?`<div class=\"contact-details\">\n        <div class=\"contact-fields\">\n          <div class=\"contact-field\"><label>Yetkili Adı Soyadı</label><input value=\"${esc(c.name)}\" oninput=\"updateContactPerson(${i},'name',this.value)\"></div>\n          <div class=\"contact-field\"><label>Görevi</label><input value=\"${esc(c.role)}\" placeholder=\"Örn. Satın Alma Müdürü\" oninput=\"updateContactPerson(${i},'role',this.value)\"></div>\n          <div class=\"contact-field\"><label>Telefon</label><input value=\"${esc(c.phone)}\" oninput=\"updateContactPerson(${i},'phone',this.value)\"></div>\n          <div class=\"contact-field\"><label>Mail</label><input value=\"${esc(c.email)}\" oninput=\"updateContactPerson(${i},'email',this.value)\"></div>\n        </div>\n        <div class=\"contact-actions\">\n          <div class=\"contact-links\">\n            ${c.phone?`<a class=\"contact-link\" href=\"tel:${esc(c.phone.replace(/\\s+/g,''))}\" onclick=\"event.stopPropagation()\">☎ Ara</a>`:''}\n            ${c.email?`<a class=\"contact-link\" href=\"mailto:${esc(c.email)}\" onclick=\"event.stopPropagation()\">✉ Mail Gönder</a>`:''}\n          </div>\n          <button type=\"button\" class=\"btn small\" onclick=\"removeContactPerson(${i})\">Sil</button>\n        </div>\n      </div>`:''}\n    </div>`\n  }).join('');\n}\nfunction toggleContactPerson(i){openContactIndex=openContactIndex===i?-1:i;renderContacts()}\nfunction updateContactPerson(i,key,value){\n  if(!contacts[i])return;\n  contacts[i][key]=value;\n}\nfunction addContactPerson(){\n  contacts.push({name:'',role:'',phone:'',email:''});\n  openContactIndex=contacts.length-1;\n  renderContacts();\n}\nfunction removeContactPerson(i){\n  contacts.splice(i,1);\n  if(openContactIndex===i)openContactIndex=-1;\n  else if(openContactIndex>i)openContactIndex--;\n  renderContacts();\n  syncPrimaryFromContacts();\n}\nfunction syncPrimaryFromContacts(){\n  const first=contacts[0]||{name:'',phone:'',email:''};\n  $('dContact').value=first.name||'';\n  $('dPhone').value=first.phone||'';\n  $('dEmail').value=first.email||'';\n}\nfunction resultOf(c){if(c.stage==='Kazanıldı')return'positive';if(c.stage==='Kaybedildi'||c.record_status==='Pasif')return'negative';if(c.stage==='Beklemede')return'waiting';return'open'}\nfunction resultLabel(c){return({positive:'Olumlu',negative:'Olumsuz',waiting:'Beklemede',open:'Sonuçlanmamış'})[resultOf(c)]}\nfunction resultBadge(c){return({positive:'pos',negative:'neg',waiting:'wait',open:'open'})[resultOf(c)]}\nfunction priorityLabel(c){const p=String(c.priority||'NORMAL');return p==='KRİTİK'?'Yüksek':p==='YÜKSEK'?'Orta':'Düşük'}\nfunction priorityClass(c){const p=String(c.priority||'NORMAL');return p==='KRİTİK'?'high':p==='YÜKSEK'?'mid':'low'}\nfunction lastMeeting(c){return meetings.filter(m=>Number(m.customer_id)===Number(c.id)).sort((a,b)=>String(b.meeting_date||b.created_at||'').localeCompare(String(a.meeting_date||a.created_at||'')))[0]||null}\nfunction isOverdue(c){return !!(c.follow_date&&c.follow_date<today()&&!['positive','negative'].includes(resultOf(c)))}\nfunction isToday(c){return c.follow_date===today()&&!['positive','negative'].includes(resultOf(c))}\nconst ANALYSIS_MARKER='[[CRM_ANALYSIS]]';\nfunction stripAnalysisMeta(text){return String(text||'').split('\\n').filter(line=>!line.startsWith(ANALYSIS_MARKER)).join('\\n')}\nfunction readCustomerAnalysis(customer){\n  const base={satisfaction:'',complaintStatus:'',complaintNote:'',lossReason:''};\n  const line=String(customer?.special_notes||'').split('\\n').find(x=>x.startsWith(ANALYSIS_MARKER));\n  if(!line)return base;\n  try{return {...base,...JSON.parse(decodeURIComponent(line.slice(ANALYSIS_MARKER.length)))}}catch{return base}\n}\nfunction currentAnalysis(){\n  return {\n    satisfaction:$('aSatisfaction')?.value||'',\n    complaintStatus:$('aComplaintStatus')?.value||'',\n    complaintNote:$('aComplaintNote')?.value.trim()||'',\n    lossReason:$('aLossReason')?.value.trim()||''\n  };\n}\nfunction analysisMetaLine(){\n  return ANALYSIS_MARKER+encodeURIComponent(JSON.stringify(currentAnalysis()));\n}\nfunction firstNote(c){const m=lastMeeting(c);if(m?.note)return String(m.note).split('\\n')[0];return stripAnalysisMeta(c.special_notes).replace(/^\\[[ xX]\\]\\s*/m,'').split('\\n')[0]||''}\nfunction monthRange(){const d=new Date(),y=d.getFullYear(),m=d.getMonth();const a=new Date(y,m,1),b=new Date(y,m+1,0);const f=x=>String(x.getDate()).padStart(2,'0')+'.'+String(x.getMonth()+1).padStart(2,'0')+'.'+x.getFullYear();$('rangeBox').textContent='▣ '+f(a)+' - '+f(b)}\nfunction fillFilters(){const cities=[...new Set(customers.map(c=>String(c.region||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'tr'));$('city').innerHTML='<option value=\"\">Tümü</option>'+cities.map(x=>`<option>${esc(x)}</option>`).join('');const secs=[...new Set(customers.flatMap(c=>String(c.categories||c.sector||'').split(',').map(x=>x.trim()).filter(Boolean)))].sort((a,b)=>a.localeCompare(b,'tr'));$('sector').innerHTML='<option value=\"\">Tümü</option>'+secs.map(x=>`<option>${esc(x)}</option>`).join('')}\nfunction counts(){const all=customers.filter(c=>c.record_status!=='Silindi');$('sTotal').textContent=all.length;$('sPositive').textContent=all.filter(c=>resultOf(c)==='positive').length;$('sWaiting').textContent=all.filter(c=>resultOf(c)==='waiting').length;$('sNegative').textContent=all.filter(c=>resultOf(c)==='negative').length;$('sOffer').textContent=all.filter(c=>String(c.stage||'').toLocaleLowerCase('tr').includes('teklif')).length;$('sFollow').textContent=all.filter(c=>c.follow_date&&!['positive','negative'].includes(resultOf(c))).length;$('sOrder').textContent=all.filter(c=>resultOf(c)==='positive').length;$('sOverdue').textContent=all.filter(isOverdue).length;const due=all.filter(isOverdue).slice(0,3);$('sideReminders').innerHTML=due.length?due.map(c=>`<div style=\"margin:6px 0\">🔴 <b>${esc(c.company)}</b><br><span>${esc(c.follow_date)}</span></div>`).join(''):'Bugün geciken takip yok.'}\nfunction filterRows(){const q=$('search').value.trim().toLocaleLowerCase('tr'),city=$('city').value,sector=$('sector').value,prio=$('priority').value,res=$('result').value,follow=$('followFilter').value;return customers.filter(c=>c.record_status!=='Silindi').filter(c=>!city||c.region===city).filter(c=>!sector||String(c.categories||c.sector||'').includes(sector)).filter(c=>!prio||c.priority===prio).filter(c=>!res||resultOf(c)===res).filter(c=>{if(!follow)return true;if(follow==='overdue')return isOverdue(c);if(follow==='today')return isToday(c);if(follow==='future')return c.follow_date>today();return true}).filter(c=>!q||[c.company,c.contact_name,c.phone,c.email,c.contacts_json,c.region,c.categories,c.sector].join(' ').toLocaleLowerCase('tr').includes(q))}\nfunction render(){visibleRows=filterRows();$('rowCount').textContent=`${visibleRows.length} firma`;const tbody=$('rows');tbody.innerHTML=visibleRows.map(c=>{const lm=lastMeeting(c),note=firstNote(c),cls=isOverdue(c)?'overdue ':'';const sel=selected&&Number(selected.id)===Number(c.id)?'selected':'';const followClass=isOverdue(c)?'over':isToday(c)?'today':'';return `<tr class=\"${cls}${sel}\"><td><span class=\"dot ${resultOf(c)==='negative'?'red':resultOf(c)==='waiting'?'amber':''}\"></span><button type=\"button\" class=\"company company-open-btn\" onclick=\"selectCustomer(${c.id})\">${esc(c.company)}</button></td><td>${esc(c.contact_name||'—')}<span class=\"person-role\">${esc(c.invoice_title||'')}</span></td><td>${esc(c.phone||parsed(c.phones_json)[0]||'—')}</td><td>${esc(c.categories||c.sector||'—')}</td><td>${esc((lm?.meeting_date||'—').slice(0,10))}</td><td><span class=\"badge ${priorityClass(c)}\">${priorityLabel(c)}</span></td><td><span class=\"badge ${resultBadge(c)}\">${resultLabel(c)}</span></td><td class=\"follow ${followClass}\">${esc(c.follow_date||'—')}</td><td><span class=\"note-check\">${note?'☑':'□'}</span></td><td><button class=\"btn small\" onclick=\"event.stopPropagation();selectCustomer(${c.id})\">Detay</button></td></tr>`}).join('');if(selected&&!visibleRows.some(c=>Number(c.id)===Number(selected.id))){selected=null;$('detailContent').classList.add('hidden');$('detailEmpty').classList.remove('hidden')}}\nfunction clearFilters(){['search','city','sector','priority','result','followFilter'].forEach(id=>$(id).value='');render()}\nfunction renderNotes(){if(!notes.length){$('noteList').innerHTML='<div style=\"font-size:10px;color:#64748b\">Henüz not yok.</div>';return}$('noteList').innerHTML=notes.map((n,i)=>`<div class=\"note-row\"><input type=\"checkbox\" ${n.done?'checked':''} onchange=\"toggleNote(${i},this.checked)\"><span class=\"note-main\" style=\"${n.done?'text-decoration:line-through;color:#94a3b8':''}\"><span>${esc(n.text)}</span><span class=\"note-date\">${esc(n.date||'Tarih bilgisi yok')}</span></span><button onclick=\"removeNote(${i})\">×</button></div>`).join('')}\nfunction parseNotes(text){return stripAnalysisMeta(text).split('\\n').map(x=>x.trim()).filter(Boolean).map(x=>{const done=/^\\[[xX]\\]/.test(x);const raw=x.replace(/^\\[[ xX]\\]\\s*/,'');const m=raw.match(/^(\\d{4}-\\d{2}-\\d{2})\\s*\\|\\s*(.*)$/);return {done,date:m?m[1]:'',text:m?m[2]:raw}})}\nfunction notesText(){\n  const normal=notes.map(n=>`[${n.done?'x':' '}] ${n.date?n.date+' | ':''}${n.text}`).join('\\n');\n  const meta=analysisMetaLine();\n  return [normal,meta].filter(Boolean).join('\\n');\n}\nfunction loadAnalysisFields(){\n  if(!selected)return;\n  const a=readCustomerAnalysis(selected);\n  $('aSatisfaction').value=a.satisfaction||'';\n  $('aComplaintStatus').value=a.complaintStatus||'';\n  $('aComplaintNote').value=a.complaintNote||'';\n  $('aLossReason').value=a.lossReason||'';\n  $('analysisSaveStatus').textContent='';\n}\nfunction addNote(){const v=$('newNote').value.trim();if(!v)return;notes.push({done:false,date:today(),text:v});$('newNote').value='';renderNotes()}\nfunction toggleNote(i,v){notes[i].done=v;renderNotes()}function removeNote(i){notes.splice(i,1);renderNotes()}\nfunction selectCustomer(id){\n  selected=customers.find(c=>Number(c.id)===Number(id));\n  if(!selected)return;\n  selectedHistory={meetings:[],offers:[],mails:[]};\n  historyLoadedId=0;\n  loadSelected();\n  document.body.classList.add('customer-open');\n  window.scrollTo({top:0,behavior:'instant'});\n}\nasync function ensureSelectedHistory(){\n  if(!selected)return;\n  const id=Number(selected.id);\n  if(historyLoadedId===id||historyLoadInFlight)return;\n  historyLoadInFlight=true;\n  const meetingBox=$('meetingHistory'),offerBox=$('offerHistory'),mailBox=$('mailHistory');\n  if(meetingBox)meetingBox.innerHTML='<div class=\"history-item\">Yükleniyor...</div>';\n  if(offerBox)offerBox.innerHTML='<div class=\"history-item\">Yükleniyor...</div>';\n  if(mailBox)mailBox.innerHTML='<div class=\"history-item\">Yükleniyor...</div>';\n  try{\n    const data=await withTimeout(api('/api/customers/'+id+'/history?ts='+Date.now()),5000,'Müşteri geçmişi');\n    if(!selected||Number(selected.id)!==id)return;\n    selectedHistory=data||{meetings:[],offers:[],mails:[]};\n    historyLoadedId=id;\n    renderHistory();\n    renderAnalysis();\n  }catch(e){\n    console.warn('Müşteri geçmişi yüklenemedi',e);\n    if(meetingBox)meetingBox.innerHTML='<div class=\"history-item\">Geçmiş şu an alınamadı. Sekmeye tekrar basarak yeniden deneyin.</div>';\n    if(offerBox)offerBox.innerHTML='<div class=\"history-item\">Geçmiş şu an alınamadı.</div>';\n    if(mailBox)mailBox.innerHTML='<div class=\"history-item\">Mail geçmişi şu an alınamadı.</div>';\n  }finally{\n    historyLoadInFlight=false;\n  }\n}\nfunction closeCustomerDetail(){\n  document.body.classList.remove('customer-open');\n  window.scrollTo({top:0,behavior:'instant'});\n}\nfunction loadSelected(){if(!selected)return;$('detailEmpty').classList.add('hidden');$('detailContent').classList.remove('hidden');$('dCompany').textContent=selected.company;$('dContact').value=selected.contact_name||'';$('dPhone').value=selected.phone||parsed(selected.phones_json)[0]||'';$('dEmail').value=selected.email||parsed(selected.emails_json)[0]||'';$('dRegion').value=selected.region||'';$('dCategories').value=selected.categories||selected.sector||'';$('dPriority').value=selected.priority||'NORMAL';$('dResultSelect').value=resultOf(selected);$('dMachine').value=selected.machine_info||'';$('dFollow').value=selected.follow_date||'';$('dLastMeeting').textContent=(lastMeeting(selected)?.meeting_date||'—').slice(0,10);$('dResultLabel').textContent=resultLabel(selected);$('dFollowLabel').textContent=selected.follow_date||'—';$('dPotential').textContent=priorityLabel(selected);if($('meetingNoteDate'))$('meetingNoteDate').value=today();if($('meetingNoteStatus'))$('meetingNoteStatus').textContent='';contacts=customerContacts(selected);openContactIndex=-1;renderContacts();syncPrimaryFromContacts();notes=parseNotes(selected.special_notes);renderNotes();loadAnalysisFields();$('overdueAlert').classList.toggle('show',isOverdue(selected));const mb=$('meetingHistory'),ob=$('offerHistory'),mailb=$('mailHistory');if(mb)mb.innerHTML='<div class=\"history-item\">Sekme açıldığında yüklenecek.</div>';if(ob)ob.innerHTML='<div class=\"history-item\">Sekme açıldığında yüklenecek.</div>';if(mailb)mailb.innerHTML='<div class=\"history-item\">Sekme açıldığında yüklenecek.</div>';renderAnalysis()}\nfunction renderHistory(){const h=selectedHistory||{meetings:[],offers:[],mails:[]};$('meetingHistory').innerHTML=h.meetings?.length?h.meetings.slice().reverse().map(m=>`<div class=\"history-item\"><b>${esc((m.meeting_date||m.created_at||'').slice(0,10))}</b> · ${esc(m.result||'Beklemede')}<div style=\"margin-top:4px\">${esc(m.note||'Not yok')}</div></div>`).join(''):'<div class=\"history-item\">Görüşme kaydı yok.</div>';$('offerHistory').innerHTML=h.offers?.length?h.offers.map(o=>`<div class=\"history-item\"><b>${esc(o.offer_no||'Teklif')}</b> · ${esc(o.status||'')} · ${Number(o.amount||0).toLocaleString('tr-TR')} ${esc(o.currency||'TRY')}<div style=\"margin-top:4px\">${esc(o.subject||o.note||'')}</div></div>`).join(''):'<div class=\"history-item\">Teklif kaydı yok.</div>';const mails=Array.isArray(h.mails)?h.mails:[];$('mailHistory').innerHTML=mails.length?mails.map(mail=>{const raw=String(mail.direction||'').toLocaleLowerCase('tr');const incoming=raw.includes('gelen')||raw.includes('in');const dir=incoming?'Gelen':'Giden';const cls=incoming?'incoming':'outgoing';return `<div class=\"mail-item ${cls}\"><div class=\"mail-head\"><div class=\"mail-subject\">${esc(mail.subject||'(Konu yok)')}</div><span class=\"mail-dir ${cls}\">${dir}</span></div><div class=\"mail-meta\">${esc((mail.mail_date||mail.created_at||'').slice(0,16))} · ${esc(mail.email||'')}</div><div class=\"mail-summary\">${esc(mail.summary||'İçerik özeti yok.')}</div></div>`}).join(''):'<div class=\"history-item\">Bu müşteriye ait mail kaydı yok.</div>'}\nfunction renderAnalysis(){if(!selected)return;const lm=lastMeeting(selected),offerCount=selectedHistory?.offers?.length||0,meetingCount=selectedHistory?.meetings?.length||0;let lines=[];lines.push(`<b>${esc(selected.company)}</b> için ${meetingCount} görüşme ve ${offerCount} teklif kaydı var.`);lines.push(`Potansiyel: <b>${priorityLabel(selected)}</b>. Sonuç: <b>${resultLabel(selected)}</b>.`);if(isOverdue(selected))lines.push(`<span style=\"color:#c51e34\"><b>Takip süresi geçmiş.</b> Öncelikli işlem gerekiyor.</span>`);else if(selected.follow_date)lines.push(`Sonraki takip: <b>${esc(selected.follow_date)}</b>.`);if(lm?.note)lines.push(`Son görüşme notu: ${esc(String(lm.note).slice(0,180))}`);$('analysisBox').innerHTML=lines.join('<br>')}\nasync function saveMeetingNote(){\n  if(!selected)return;\n  const note=$('meetingNoteText').value.trim();\n  const date=$('meetingNoteDate').value||today();\n  const result=$('meetingNoteResult').value||'Beklemede';\n  if(!note){$('meetingNoteStatus').textContent='Önce görüşme/not yazın.';return}\n  const btn=$('meetingNoteSave');\n  btn.disabled=true;\n  $('meetingNoteStatus').textContent='Kaydediliyor...';\n  try{\n    await api('/api/meetings',{method:'POST',body:JSON.stringify({customer_id:selected.id,meeting_date:date,note,result})});\n    $('meetingNoteText').value='';\n    $('meetingNoteDate').value=today();\n    $('meetingNoteStatus').textContent='Kaydedildi.';\n    historyLoadedId=0;\n    historyLoadInFlight=false;\n    await ensureSelectedHistory();\n    loadMeetingData();\n  }catch(e){\n    $('meetingNoteStatus').textContent='Kaydedilemedi: '+(e?.message||e);\n  }finally{\n    btn.disabled=false;\n  }\n}\nasync function saveCustomerAnalysis(){\n  if(!selected)return;\n  $('analysisSaveStatus').textContent='Kaydediliyor...';\n  try{\n    await saveCustomer();\n    switchTab('analysis');\n    $('analysisSaveStatus').textContent='Müşteri analizi kaydedildi.';\n  }catch(e){\n    $('analysisSaveStatus').textContent='Kaydedilemedi: '+(e?.message||e);\n    throw e;\n  }\n}\nfunction focusEdit(){$('dContact').focus()}\nasync function saveCustomer(){\n  if(!selected)return;\n  const desired=$('dResultSelect').value;\n  const cleanContacts=contacts.map(x=>({name:String(x.name||'').trim(),role:String(x.role||'').trim(),phone:String(x.phone||'').trim(),email:String(x.email||'').trim()})).filter(x=>x.name||x.role||x.phone||x.email);\n  if(!cleanContacts.length&&($('dContact').value.trim()||$('dPhone').value.trim()||$('dEmail').value.trim()))cleanContacts.push({name:$('dContact').value.trim(),role:'',phone:$('dPhone').value.trim(),email:$('dEmail').value.trim()});\n  const phones=cleanContacts.map(x=>x.phone).filter(Boolean),emails=cleanContacts.map(x=>x.email).filter(Boolean);\n  let stage=selected.stage||'Yeni Lead';\n  if(desired==='waiting')stage='Beklemede';\n  else if(desired==='open'&&['Kazanıldı','Kaybedildi','Beklemede'].includes(stage))stage='İlk Görüşme';\n  const primary=cleanContacts[0]||{name:$('dContact').value.trim(),phone:$('dPhone').value.trim(),email:$('dEmail').value.trim()};\n  const payload={company:selected.company,contact_name:primary.name||'',phones,emails,contacts:cleanContacts,region:$('dRegion').value.trim(),categories:$('dCategories').value.split(',').map(x=>x.trim()).filter(Boolean),priority:$('dPriority').value,stage,follow_date:$('dFollow').value,invoice_title:selected.invoice_title||'',tax_office:selected.tax_office||'',tax_number:selected.tax_number||'',invoice_address:selected.invoice_address||'',special_notes:notesText(),machine_info:$('dMachine').value.trim()};\n\n  await api('/api/customers/'+selected.id,{method:'PUT',body:JSON.stringify(payload)});\n  if(desired==='positive'||desired==='negative')await api('/api/customers/'+selected.id+'/result',{method:'PUT',body:JSON.stringify({result:desired==='positive'?'Olumlu':'Olumsuz'})});\n\n  selected={...selected,...payload,phone:phones[0]||'',email:emails[0]||'',phones_json:JSON.stringify(phones),emails_json:JSON.stringify(emails),contacts_json:JSON.stringify(cleanContacts)};\n  if(desired==='positive')selected.stage='Kazanıldı';\n  if(desired==='negative'){selected.stage='Kaybedildi';selected.record_status='Pasif'}\n  const pos=customers.findIndex(c=>Number(c.id)===Number(selected.id));\n  if(pos>=0)customers[pos]=selected;\n  writeCustomerCache(customers);\n  contacts=cleanContacts;\n  loadSelected();\n  setTimeout(refreshPortfolioDataSilently,0);\n}\nasync function createReminder(){if(!selected)return;const date=$('dFollow').value,time=$('dFollowTime').value||'10:00';if(!date){alert('Önce sonraki işlem tarihini seçin.');return}const note=$('dReminderNote').value.trim()||selected.company+' takip';await api('/api/meetings',{method:'POST',body:JSON.stringify({customer_id:selected.id,meeting_date:today(),note:'Takip hatırlatması oluşturuldu: '+note,next_follow_date:date,remind_at:date+'T'+time,remind_note:note,result:'Beklemede'})});selected.follow_date=date;const pos=customers.findIndex(c=>Number(c.id)===Number(selected.id));if(pos>=0)customers[pos]=selected;writeCustomerCache(customers);loadSelected();setTimeout(loadMeetingData,0)}\nfunction switchTab(name){document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===name));document.querySelectorAll('.tabpane').forEach(x=>x.classList.add('hidden'));$('tab'+name[0].toUpperCase()+name.slice(1)).classList.remove('hidden');if(name!=='general')ensureSelectedHistory()}\ndocument.querySelectorAll('.tab').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));['search','city','sector','priority','result','followFilter'].forEach(id=>$(id).addEventListener(id==='search'?'input':'change',render));\nfunction exportCsv(){const head=['Firma','Kişi','Telefon','Mail','Bölge','İş Alanı','Sonuç','Takip'];const body=visibleRows.map(c=>[c.company,c.contact_name,c.phone,c.email,c.region,c.categories||c.sector,resultLabel(c),c.follow_date]);const csv=[head,...body].map(r=>r.map(v=>'\"'+String(v||'').replaceAll('\"','\"\"')+'\"').join(';')).join('\\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\\ufeff'+csv],{type:'text/csv'}));a.download='musteri-portfoyu.csv';a.click();URL.revokeObjectURL(a.href)}\nfunction normalizeRows(data,key){\n  if(Array.isArray(data))return data;\n  if(data&&Array.isArray(data[key]))return data[key];\n  if(data&&Array.isArray(data.results))return data.results;\n  return [];\n}\nfunction withTimeout(promise,ms,label){\n  return Promise.race([\n    promise,\n    new Promise((_,reject)=>setTimeout(()=>reject(new Error(label+' zaman aşımına uğradı')),ms))\n  ]);\n}\nconst PORTFOLIO_CACHE_KEY='crm_portfolio_customers_v1';\n\nfunction readCustomerCache(){\n  try{\n    const rows=JSON.parse(localStorage.getItem(PORTFOLIO_CACHE_KEY)||'[]');\n    return Array.isArray(rows)?rows:[];\n  }catch{\n    return [];\n  }\n}\n\nfunction writeCustomerCache(rows){\n  try{\n    localStorage.setItem(PORTFOLIO_CACHE_KEY,JSON.stringify(rows||[]));\n  }catch{}\n}\n\nasync function loadMeetingData(){\n  if(meetingLoadInFlight)return;\n  meetingLoadInFlight=true;\n  try{\n    const data=await withTimeout(\n      api('/api/portfolio-meetings?ts='+Date.now()),\n      5000,\n      'Görüşme verisi'\n    );\n    meetings=normalizeRows(data,'meetings');\n    counts();\n    if(document.body.classList.contains('customer-open')&&selected){\n      $('dLastMeeting').textContent=(lastMeeting(selected)?.meeting_date||'—').slice(0,10);\n      renderAnalysis();\n    }else{\n      render();\n    }\n  }catch(e){\n    console.warn('Görüşmeler arka planda yüklenemedi; müşteri listesi korunuyor.',e);\n  }finally{\n    meetingLoadInFlight=false;\n  }\n}\n\nasync function refreshPortfolioDataSilently(){\n  if(portfolioLoadInFlight)return;\n  portfolioLoadInFlight=true;\n  try{\n    const bundle=await withTimeout(api('/api/portfolio-bootstrap?ts='+Date.now()),4000,'Portföy verisi');\n    const fresh=normalizeRows(bundle,'customers').filter(c=>c&&c.record_status!=='Silindi');\n    if(!fresh.length)return;\n    customers=fresh;\n    writeCustomerCache(customers);\n    fillFilters();\n    counts();\n    if(!document.body.classList.contains('customer-open'))render();\n  }catch(e){\n    console.warn('Sessiz portföy yenilemesi atlandı',e);\n  }finally{\n    portfolioLoadInFlight=false;\n  }\n}\nasync function loadAll(reselect){\n  if(portfolioLoadInFlight)return;\n\n  const cached=readCustomerCache().filter(c=>c&&c.record_status!=='Silindi');\n  if(cached.length&&!customers.length){\n    customers=cached;\n    meetings=[];\n    fillFilters();\n    counts();\n    render();\n    $('sideReminders').innerHTML='<span style=\"color:#bfdbfe\">Son müşteri listesi hazır. Güncel veri kontrol ediliyor...</span>';\n  }else if(!customers.length){\n    $('sideReminders').textContent='Müşteriler yükleniyor...';\n  }\n\n  portfolioLoadInFlight=true;\n  try{\n    const bundle=await withTimeout(api('/api/portfolio-bootstrap?ts='+Date.now()),4000,'Portföy verisi');\n    const fresh=normalizeRows(bundle,'customers').filter(c=>c&&c.record_status!=='Silindi');\n    if(fresh.length){\n      customers=fresh;\n      writeCustomerCache(customers);\n      fillFilters();\n      counts();\n      if(!document.body.classList.contains('customer-open'))render();\n      $('sideReminders').textContent='';\n    }\n  }catch(e){\n    console.warn('Canlı portföy verisi alınamadı; mevcut liste korunuyor.',e);\n    if(customers.length){\n      $('sideReminders').innerHTML='<span style=\"color:#fde68a\">Bağlantı yavaş. Mevcut müşteri listesi kullanılmaya devam ediyor.</span>';\n    }else{\n      $('sideReminders').innerHTML='<span style=\"color:#fecaca\">Portföy verisi şu an alınamadı. Yenile düğmesiyle tekrar deneyin.</span>';\n    }\n  }finally{\n    portfolioLoadInFlight=false;\n  }\n\n  if(reselect){\n    const current=customers.find(c=>Number(c.id)===Number(reselect));\n    if(current)selectCustomer(reselect);\n  }\n\n  if(meetingDelayTimer)clearTimeout(meetingDelayTimer);\n  meetingDelayTimer=setTimeout(()=>{meetingDelayTimer=null;loadMeetingData()},700);\n}\nmonthRange();\n(function(){\n  const el=document.getElementById('dailyEvalDate');\n  if(el)el.textContent=new Intl.DateTimeFormat('tr-TR',{timeZone:'Europe/Istanbul',day:'2-digit',month:'long',year:'numeric'}).format(new Date());\n})();\nloadAll();\n</script>\n</body>\n</html>";
